// Yalniz toplulastirma. Nedensellik yorumu yok; n<5 icin 'yetersiz'. Sayi uretilmez, yalniz girdi toplanir.
const satirlar = $input.all().map(i => i.json);
const gruplar = {};
for (const s of satirlar) {
  const k = s.kanal || 'bilinmiyor';
  gruplar[k] = gruplar[k] || { gonderi: 0, erisim: 0, kaydetme: 0, paylasim: 0, baglanti_tiki: 0 };
  gruplar[k].gonderi += 1;
  for (const m of ['erisim','kaydetme','paylasim','baglanti_tiki']) gruplar[k][m] += Number(s[m] || 0);
}
const cikti = Object.entries(gruplar).map(([kanal, g]) => ({ kanal, ...g, uyari: g.gonderi < 5 ? 'yetersiz veri (n<5), karar verilmez' : 'oran yorumu insan yapar' }));
return cikti.map(j => ({ json: j }));
